class CartScreen extends StatefulWidget {
  const CartScreen({super.key});

  @override
  State<CartScreen> createState() => _CartScreenState();
}

class _CartScreenState extends State<CartScreen> {
  Map<Phone, int> quantity = {};

  @override
  void initState() {
    super.initState();
    for (var phone in cart) {
      quantity[phone] = 1;
    }
  }

  double getTotalPrice() {
    double total = 0;
    quantity.forEach((phone, qty) {
      total += phone.price * qty;
    });
    return total;
  }

  Widget buildImage(String image) {
    if (image.startsWith("data:image")) {
      final base64Str = image.split(",").last;
      return Image.memory(
        base64Decode(base64Str),
        width: 90,
        height: 90,
        fit: BoxFit.cover,
      );
    } else {
      return Image.network(
        image,
        width: 90,
        height: 90,
        fit: BoxFit.cover,
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: const Text("Giỏ hàng của bạn"), // Đổi text giống hình minh họa
        backgroundColor: Colors.amber,
      ),
      body: cart.isEmpty
          ? const Center(
              child: Text(
                "Bạn chưa có sản phẩm nào vô giỏ hàng!!!", // Đổi text giống hình
                style: TextStyle(fontSize: 18),
              ),
            )
          : Column(
              children: [
                Expanded(
                  child: ListView.builder(
                    itemCount: cart.length,
                    itemBuilder: (context, index) {
                      final phone = cart[index];
                      int qty = quantity[phone]!;

                      return Card(
                        margin: const EdgeInsets.all(10),
                        elevation: 4,
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                        child: Padding(
                          padding: const EdgeInsets.all(10),
                          child: Row(
                            children: [
                              ClipRRect(
                                borderRadius: BorderRadius.circular(10),
                                child: buildImage(phone.image),
                              ),
                              const SizedBox(width: 12),
                              Expanded(
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Text(
                                      phone.name,
                                      style: const TextStyle(
                                        fontSize: 16,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                                    const SizedBox(height: 5),
                                    Text(
                                      "${formatMoney(phone.price)} đ",
                                      style: const TextStyle(
                                        fontSize: 16,
                                        color: Colors.red,
                                        fontWeight: FontWeight.bold,
                                      ),
                                    ),
                                    const SizedBox(height: 10),
                                    Row(
                                      children: [
                                        IconButton(
                                          icon: const Icon(Icons.remove),
                                          onPressed: () {
                                            setState(() {
                                              if (qty > 1) {
                                                quantity[phone] = qty - 1;
                                              }
                                            });
                                          },
                                        ),
                                        Text(
                                          qty.toString(),
                                          style: const TextStyle(fontSize: 16),
                                        ),
                                        IconButton(
                                          icon: const Icon(Icons.add),
                                          onPressed: () {
                                            setState(() {
                                              quantity[phone] = qty + 1;
                                            });
                                          },
                                        ),
                                      ],
                                    ),
                                  ],
                                ),
                              ),
                              // ----- SỬA LOGIC NÚT XÓA TẠI ĐÂY -----
                              IconButton(
                                icon: const Icon(
                                  Icons.delete,
                                  color: Colors.black, // Hình mẫu để icon màu đen
                                ),
                                onPressed: () {
                                  showDialog(
                                    context: context,
                                    builder: (context) {
                                      return AlertDialog(
                                        title: const Text("Xác nhận"),
                                        content: const Text(
                                            "Bạn muốn loại bỏ sản phẩm này ra khỏi giỏ hàng"),
                                        actions: [
                                          TextButton(
                                            onPressed: () {
                                              Navigator.pop(context);
                                            },
                                            child: const Text("Không"),
                                          ),
                                          TextButton(
                                            onPressed: () {
                                              setState(() {
                                                quantity.remove(phone);
                                                // Xóa hoàn toàn sản phẩm này khỏi list cart
                                                cart.removeWhere((p) => p.name == phone.name); 
                                              });
                                              Navigator.pop(context);
                                            },
                                            child: const Text("Đồng ý"),
                                          ),
                                        ],
                                      );
                                    },
                                  );
                                },
                              )
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                ),
                Container(
                  padding: const EdgeInsets.all(15),
                  decoration: const BoxDecoration(
                    color: Colors.white,
                    boxShadow: [
                      BoxShadow(
                        blurRadius: 5,
                        color: Colors.grey,
                      )
                    ],
                  ),
                  child: Row(
                    mainAxisAlignment: MainAxisAlignment.spaceBetween,
                    children: [
                      Text(
                        "Tổng tiền: ${formatMoney(getTotalPrice())} đ",
                        style: const TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color: Colors.red,
                        ),
                      ),
                      ElevatedButton(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: Colors.green,
                          foregroundColor: Colors.white,
                        ),
                        onPressed: () {
                          showDialog(
                            context: context,
                            builder: (context) {
                              return AlertDialog(
                                title: const Text("Thanh toán"),
                                content: const Text("Bạn đã thanh toán xong giỏ hàng"),
                                actions: [
                                  TextButton(
                                    onPressed: () {
                                      setState(() {
                                        cart.clear();
                                        quantity.clear();
                                      });
                                      Navigator.pop(context);
                                    },
                                    child: const Text("OK"),
                                  ),
                                ],
                              );
                            },
                          );
                        },
                        child: const Text("Thanh toán"),
                      )
                    ],
                  ),
                )
              ],
            ),
    );
  }
}

String formatMoney(num number) {
  return number
      .toStringAsFixed(0)
      .replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'), (match) => '.');
}
